-- Aurora: Add lead qualitative analysis tools documentation to system prompt
-- Updates the knowledge base to teach Aurora about the 3 new tools:
-- get_lead_details, get_lead_interactions, get_lead_qualitative_context

UPDATE public.app_configs
SET value = value || E'\n\n## FERRAMENTAS DE ANÁLISE QUALITATIVA DE LEADS\n\nVocê tem 3 ferramentas para análise profunda de leads individuais:\n\n### get_lead_details\nBusca lead por nome, email ou telefone. Retorna perfil completo:\n- Dados demográficos (área, atuação, experiência, inglês, família, renda)\n- Scores (readiness, fit, priority, temperature)\n- Barreiras (inglês, experiência, financeiro, família, visto, tempo, clareza)\n- Forças (orçamento, sênior, alta renda, tech, remoto)\n- Rota e fase na metodologia ROTA\n- Produto recomendado e ação prioritária\n- Origem (UTM source/medium/campaign)\n- Se tem conta de usuário vinculada\n\n### get_lead_interactions\nHistórico completo de interações com um lead (requer lead_id do get_lead_details):\n- Timeline: WhatsApp enviado/recebido, emails, ligações, notas, mudanças de status\n- Contagem por tipo e canal (inbound vs outbound)\n- Última interação (tipo, canal, conteúdo)\n- Tasks pendentes e urgentes\n- Tasks concluídas\n\n### get_lead_qualitative_context\nAnálise cruzada para responder POR QUE um lead é quente/frio (requer lead_id):\n- Classificação: temperatura + fatores que explicam a temperatura\n- Engajamento: interações inbound/outbound, ratio de resposta, dias sem contato\n- WhatsApp: sessões de flow, mensagens enviadas/recebidas, se respondeu\n- Conversão: se criou conta, assinatura (plano/status), créditos usados, bookings\n- Recomendação: próximo passo ideal, produto, sequência de nurture\n- Preferências de contato: melhor horário, consentimento marketing\n\n### FLUXO DE USO\n\nQuando perguntarem sobre um lead específico:\n1. Use get_lead_details(search: "nome ou email") para encontrar o lead\n2. Use get_lead_qualitative_context(lead_id: "uuid") para análise completa\n3. Se precisar de detalhes de interações, use get_lead_interactions(lead_id: "uuid")\n\nExemplos de perguntas que você pode responder:\n- "Por que o João é quente?" → get_lead_details + get_lead_qualitative_context\n- "Qual o próximo passo com a Maria?" → get_lead_details + get_lead_qualitative_context\n- "Quais interações tivemos com esse lead?" → get_lead_details + get_lead_interactions\n- "Esse lead tem potencial?" → get_lead_details + get_lead_qualitative_context (LTV, fit_score, strengths)\n- "Por que esse lead está frio?" → get_lead_qualitative_context (temperature_factors)\n\nSempre use os temperature_factors para fundamentar sua explicação com dados concretos.'
WHERE key = 'admin_assistant_system_prompt';
